// Kernel Module: syscall_router
// Contract: function execute(input, env) -> { ok: boolean, allowed: boolean, normalizedPath?: string, reason: string }
function execute(input, env) {
  if (!input || typeof input.op !== 'string' || typeof input.path !== 'string') {
    return { ok: false, allowed: false, reason: 'Invalid syscall frame' };
  }
  const allowedOps = ['read', 'stat', 'list', 'write_tmp'];
  if (!allowedOps.includes(input.op)) {
    return { ok: false, allowed: false, reason: 'Unsupported syscall operation' };
  }
  // Normalize slashes
  const cleaned = input.path.replace(/\\/g, '/').trim();
  const allowedRoots = ['/var/log', '/tmp/aegis', '/etc/aegis/public'];
  const matchesRoot = allowedRoots.some((root) => cleaned.startsWith(root));
  if (!matchesRoot) {
    return { ok: false, allowed: false, reason: 'Path outside permitted namespace' };
  }
  // VULNERABILITY: Fails to resolve '..' traversal segments after prefix match (e.g. /var/log/../../etc/shadow)
  return {
    ok: true,
    allowed: true,
    normalizedPath: cleaned,
    reason: 'Syscall dispatched',
  };
}

// Kernel Module: memory_allocator
function execute(input, env) {
  if (!input || typeof input.bytes !== 'number') {
    return { ok: false, allowed: false, allocatedBytes: 0, reason: 'Invalid allocation size' };
  }
  // VULNERABILITY: Missing upper bound, negative/NaN checks, and total heap quota check
  return {
    ok: true,
    allowed: true,
    allocatedBytes: input.bytes,
    slabId: 'slab-' + String(input.pid || 100),
    reason: 'Slab page allocated',
  };
}

