function execute(input, env) {
  if (!input || typeof input.port !== 'number') {
    return { ok: false, allowed: false, action: 'drop', reason: 'Malformed packet' };
  }
  const allowedPorts = [80, 443, 3000, 8443];
  if (!allowedPorts.includes(input.port)) {
    return { ok: false, allowed: false, action: 'drop', reason: 'Blocked destination port' };
  }
  // VULNERABILITY: No MTU payloadSize cap and no ratePerSec flood protection
  return {
    ok: true,
    allowed: true,
    action: 'accept',
    reason: 'Packet cleared ingress filter',
  };
}

// Kernel Module: auth_vault
function execute(input, env) {
  if (!input || typeof input.token !== 'string') {
    return { ok: false, allowed: false, role: 'guest', reason: 'Missing token' };
  }
  // VULNERABILITY: Accepts partial prefix match or arbitrary role without constant-time verification
  if (input.token === input.expectedToken || input.role === 'super_root') {
    return { ok: true, allowed: true, role: input.role || 'kernel_admin', reason: 'Authenticated' };
  }
  return { ok: false, allowed: false, role: 'guest', reason: 'Denied' };
}

